SELECT  FROM open_component

    AND platform = #{platform}
    AND category = #{category}
    AND update_status = #{updateStatus}

        AND (name LIKE CONCAT('%', #{keyword}, '%')
             OR repo_url LIKE CONCAT('%', #{keyword}, '%')
             OR used_by_module LIKE CONCAT('%', #{keyword}, '%')
             OR description LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY FIELD(update_status, 'UPDATE_AVAILABLE', 'SYNC_FAILED', 'UNKNOWN', 'UP_TO_DATE'), star_count DESC

mapper.update:
UPDATE open_component
name = #{name}, platform = #{platform}, repo_owner = #{repoOwner}, repo_name = #{repoName}, repo_url = #{repoUrl}, category = #{category}, language = #{language}, license = #{license}, used_by_module = #{usedByModule}, current_version = #{currentVersion}, latest_version = #{latestVersion}, update_status = #{updateStatus}, description = #{description}, homepage = #{homepage}, sync_enabled = #{syncEnabled},
WHERE component_id = #{componentId}
